    line_color.rgb = select*line_color.rgb + (1.0 - select)*fill_color.rgb;
    // Similarly, if we want a transparent fill.
    select = float(bool(fill_color.a));
    fill_color.rgb = select*fill_color.rgb + (1.0 - select)*line_color.rgb;

